Entity Ponto() {
 action __init__(self, x) { self.x = x }
}
p = Ponto(7)
post(p.x)

Entity C() {
 action __init__(self, n) { self.n = n }
 action get(self) { return self.n }
}
post(C(9).get())

Entity Conta() {
 private saldo: int = 0
 public reaction deposita(self, v) { self.saldo = self.saldo + v }
 public reaction ver(self) { return self.saldo }
}
c = Conta()
c.deposita(50)
post(c.ver())

Entity Pessoa() {
 public reaction __init__(self, nome) { self.nome = nome }
}
p = Pessoa("Ana")
post(p.nome)
